import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { startApi, type Api } from "./support/api.js";

let api: Api;
beforeAll(async () => { api = await startApi(); await api.login(); });
afterAll(async () => { await api.close(); });

describe("orders API", () => {
  // cites: REQ-012/AC-001, IF-002@1.0.0#createOrder
  it("creates an order", async () => {
    const res = await api.request("POST", "/orders", { item: "Item A" });
    expect(res.statusCode).toBe(201);
  });

  // cites: REQ-012/AC-002, R-004
  it("refuses to cancel a shipped order", async () => {
    const res = await api.request("POST", "/orders/shipped/cancel");
    expect(res.json().code).toBe("order.not_cancellable");
  });
});
